#!/system/bin/sh
# Mewgenics (PPSA37318): нативные правки горячего кода в app.elf.
# Аллокатор игры (TLSF, va 0xe21000..) ищет старший единичный бит циклом до 64 итераций (bt/dec/inc/cmp);
# под box64 это 17% всего кода игры в бою. Циклы старшего бита заменены на lzcnt (box64: одна CLZ)
# с тем же состоянием на обоих выходах: найден бит — счётчик = clz, индекс = 63 - clz; ноль — 64 и -1,
# флаги выхода из той же cmp счётчик,0x40. Сайты (va): 0xe2154f (поиск в malloc), 0xe21639, 0xe21c3b (free) и ещё
# восемь таких же; поиск младшего бита (0xe21fb3, 64 бита) — tzcnt; четыре поиска младшего бита 32-битной маски
# (0xe215c9, 0xe215f2, 0xe21a55, 0xe21a85) — tzcnt с переходом на прежний выход «нет бита» (там ставится 0x40).
# Записи в память внутри участков сохранены. Два цикла без видимой инициализации счётчика (0xe212e0, 0xe213b0) не тронуты.
# Запуск (игра закрыта): su -c 'sh mew-native.sh'      откат: su -c 'sh mew-native.sh undo'
# Каждое место ставится, только если там исходные байты; уже исправленное пропускается; иначе ничего не меняется.
# После правки старый кеш трансляции app.elf (DynaCache) удаляется: в его имени mtime файла, он бы не подошёл.
G=/data/data/org.anyps5.android/files/games/PPSA37318
CACHE=/data/data/org.anyps5.android/files/.cache/box64
cd "$G" || { echo "нет $G"; exit 1; }
if pidof org.anyps5.android > /dev/null; then echo "игра запущена: app.elf открыт, правка только при закрытой игре"; exit 1; fi
drop_cache() { rm -f "$CACHE"/app.elf-*.box64 && echo "кеш трансляции app.elf удалён"; }
if [ "$1" = undo ]; then
  [ -f app.elf.pre-native ] && cp -p app.elf.pre-native app.elf && echo "возвращён app.elf до нативных правок" && drop_cache || echo "нет app.elf.pre-native"
  exit 0
fi
SITES='
