bytes_at() { od -An -tx1 -j "$1" -N"$2" app.elf | tr -d ' \n'; }
printf '%s\n' "$SITES" | while read -r off old new oct; do
  [ -z "$off" ] && continue
  cur=$(bytes_at "$off" $(( ${#old} / 2 )))
  if [ "$cur" = "$new" ]; then echo "$off: уже исправлено"
  elif [ "$cur" = "$old" ]; then echo "$off: будет исправлено"
  else echo "$off: НЕОЖИДАННЫЕ байты $cur"; fi
done > /data/local/tmp/mew-native.check
cat /data/local/tmp/mew-native.check
grep -q "НЕОЖИДАННЫЕ" /data/local/tmp/mew-native.check && { echo "ничего не изменено: другая сборка app.elf"; exit 1; }
grep -q "будет исправлено" /data/local/tmp/mew-native.check || { echo "всё уже исправлено"; exit 0; }
[ -f app.elf.pre-native ] || cp -p app.elf app.elf.pre-native
printf '%s\n' "$SITES" | while read -r off old new oct; do
  [ -z "$off" ] && continue
  [ "$(bytes_at "$off" $(( ${#old} / 2 )))" = "$old" ] && printf "$oct" | dd of=app.elf bs=1 seek="$off" conv=notrunc 2>/dev/null
done
printf '%s\n' "$SITES" | while read -r off old new oct; do
  [ -z "$off" ] && continue
  [ "$(bytes_at "$off" $(( ${#old} / 2 )))" = "$new" ] || echo "$off: НЕ ЗАПИСАЛОСЬ"
done
drop_cache
echo "готово (копия исходного файла: app.elf.pre-native)"
